head.script:
scwin.getType = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var dataSetNm = "";
    var returnInfo;
    var inputType = "";
    var strLnupItmCd = "";
    strLnupItmCd = DS_ztpm_lnup_itm_2000.getCellData(rowIndex, "lnup_itm_cd");
    //			dataSetNm    = strDataNm.getCellData( rowIndex, "hide_dataset_nm") ;
    dataSetNm = (rowIndex % 2 == 0) ? "DS_LNUP_ITM484" : "DS_LNUP_ITM537";
    dataSetNm = "data:" + dataSetNm;
    var colNm = "hide_" + info.colID;
    try {
        inputType = "select"
        switch (inputType) {
            case "select":
                returnInfo = {
                    id: "dynamic_select_" + strLnupItmCd + "_" + rowIndex + "_" + colIndex,
                    inputType: "select",
                    options: {
                        viewType: "icon"
                    },
                    itemSet: {
                        nodeset: dataSetNm,
                        label: "lnup_dtl_itm_nm",
                        value: "lnup_dtl_itm_cd"
                    }
                };
                break;
            case "text" + strLnupItmCd:
                returnInfo = {
                    id: "dynamic_text_" + strLnupItmCd + "_" + rowIndex + "_" + colIndex,
                    readOnly: "true",
                    inputType: "text",
                    options: {}
                };
        }
        return returnInfo;
    } catch (e) {}
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 속성값항목의 필드를 마우스로 선택한다.
    //1. Run the sample file and select the field of the attribute value item with the mouse.
    //Verify step 1. The selectable values of the attribute value items are displayed. If the contents are long, they are displayed as being stretched sideways (previously not selected).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_tab2Info_cell_0_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_grd_tab2Info___selectbox_0_lnup_dtl_itm_cd_2000_dynamic_select_undefined_0_3_itemTable').css('display') == 'block'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
